// Package sample generates the self-contained input fixtures used by the
// self-test. Nothing is read from disk outside the process: every stream is
// built deterministically from a seed.
package sample

import (
	"bytes"
	"fmt"
	"math/rand"
	"os"
	"path/filepath"

	pionrtp "github.com/pion/rtp"

	"rtp-rebuild/internal/ingest"
	"rtp-rebuild/internal/rtcp"
)

// StartUnixNano is the fixed capture start recorded in every stream header.
// Fixing it keeps generated bytes identical for a given seed.
const StartUnixNano int64 = 1_700_000_000_000_000_000

// StartUnixMillis is StartUnixNano in milliseconds.
const StartUnixMillis = StartUnixNano / 1_000_000

const (
	// DefaultPackets is the packet count of the healthy stream.
	DefaultPackets = 100
	// PacketInterval is the timestamp step between healthy packets (33.3 ms).
	PacketInterval uint32 = 3000
	// PayloadSize is the payload length of every generated packet.
	PayloadSize = 32
	// SRRC is the single SSRC used by all generated streams.
	SSRC uint32 = 0x1BADB002
	// PayloadType is the generated RTP payload type.
	PayloadType uint8 = 96
)

// Spec describes one generated stream.
type Spec struct {
	Name string
	// Packets is the number of distinct media packets to generate.
	Packets int
	// OutOfOrder shuffles a bounded window of packets.
	OutOfOrder bool
	// Duplicates repeats this many packets a second time.
	Duplicates int
	// Drop lists sequence indexes that are never sent.
	Drop []int
	// GapAfter inserts a stall after this sequence index: the next packet's
	// timestamp jumps by GapTicks.
	GapAfter int
	GapTicks uint32
	// StartSeq is the first sequence number (wrap tests use 65500).
	StartSeq uint16
	// StartTS is the first timestamp (wrap tests use 0xFFFF0000).
	StartTS uint32
	// TruncateRTCP cuts the last RTCP record short by TruncateBytes.
	TruncateRTCP  bool
	TruncateBytes int
	// BadEvents adds event lines that cannot be aligned.
	BadEvents int
}

// Stream is a generated stream and its expected shape.
type Stream struct {
	Spec Spec
	// Path is where the stream was written.
	Path string
	// Bytes is the encoded stream.
	Bytes []byte
	// RTPSent is the number of RTP records written, including duplicates.
	RTPSent int
	// UniqueSent is distinct sequence indexes written.
	UniqueSent int
	// TruncatedRTCPOffset is the absolute offset of the truncated RTCP record,
	// or -1 when the stream has no truncation.
	TruncatedRTCPOffset int64
}

// FaultSpec returns the combined fault stream: reordering, duplicates, loss, a
// stall, a timestamp wrap and a truncated RTCP record.
func FaultSpec() Spec {
	return Spec{
		Name:          "fault",
		Packets:       60,
		OutOfOrder:    true,
		Duplicates:    3,
		Drop:          []int{20, 21},
		GapAfter:      40,
		GapTicks:      60000,
		StartSeq:      65480,
		StartTS:       0xFFFF0000,
		TruncateRTCP:  true,
		TruncateBytes: 6,
		BadEvents:     1,
	}
}

// NormalSpec returns the healthy stream.
func NormalSpec() Spec {
	return Spec{Name: "normal", Packets: DefaultPackets, StartSeq: 1000}
}

// Write builds the stream and writes it to dir/name.rtrb.
func Write(dir string, spec Spec, seed int64) (*Stream, error) {
	if spec.Packets <= 0 {
		spec.Packets = DefaultPackets
	}
	data, st, err := build(spec, seed)
	if err != nil {
		return nil, err
	}
	if err := os.MkdirAll(dir, 0o755); err != nil {
		return nil, fmt.Errorf("sample: create %s: %w", dir, err)
	}
	path := filepath.Join(dir, spec.Name+".rtrb")
	if err := writeFileAtomic(path, data); err != nil {
		return nil, err
	}
	st.Path = path
	return st, nil
}

// Build returns the encoded stream without touching the filesystem.
func Build(spec Spec, seed int64) ([]byte, error) {
	data, _, err := build(spec, seed)
	return data, err
}

func build(spec Spec, seed int64) ([]byte, *Stream, error) {
	var buf bytes.Buffer
	w, err := ingest.NewWriter(&buf, StartUnixNano)
	if err != nil {
		return nil, nil, err
	}
	st := &Stream{Spec: spec, TruncatedRTCPOffset: -1}
	rng := rand.New(rand.NewSource(seed))

	drop := map[int]bool{}
	for _, d := range spec.Drop {
		drop[d] = true
	}

	type wire struct {
		data []byte
		// index is the original media index, used to duplicate deterministically.
		index int
	}
	var rtpRecords []wire
	var rtcpRecords [][]byte
	tsBase := spec.StartTS
	for i := 0; i < spec.Packets; i++ {
		// The stall shifts the whole tail, so every later packet keeps its
		// nominal spacing and only the one gap is anomalous.
		ts := tsBase + uint32(i)*PacketInterval
		if spec.GapTicks > 0 && i > spec.GapAfter {
			ts += spec.GapTicks
		}
		if drop[i] {
			continue
		}
		seq := spec.StartSeq + uint16(i)
		pkt := &pionrtp.Packet{
			Header: pionrtp.Header{
				Version:        2,
				SequenceNumber: seq,
				Timestamp:      ts,
				SSRC:           SSRC,
				PayloadType:    PayloadType,
				Marker:         i == spec.Packets-1,
			},
			Payload: payloadFor(seq),
		}
		raw, err := pkt.Marshal()
		if err != nil {
			return nil, nil, fmt.Errorf("sample: marshal rtp: %w", err)
		}
		rtpRecords = append(rtpRecords, wire{data: raw, index: i})
		st.UniqueSent++
		if spec.OutOfOrder {
			// Shuffle locally: swap with a neighbour a few slots ahead.
			if i > 0 && rng.Intn(4) == 0 {
				j := len(rtpRecords) - 1 - rng.Intn(min(3, len(rtpRecords)))
				rtpRecords[j], rtpRecords[len(rtpRecords)-1] = rtpRecords[len(rtpRecords)-1], rtpRecords[j]
			}
		}
		if i%25 == 24 {
			rtcpRecords = append(rtcpRecords, rtcp.SenderReport(SSRC, ts, uint64(i)*1_000_000, uint32(i), uint32(i*PayloadSize),
				[]rtcp.ReportBlock{{
					SSRC:           SSRC ^ 0xFFFF,
					FractionLost:   uint8(rng.Intn(3)),
					CumulativeLost: int32(rng.Intn(4)),
					HighestSeq:     uint32(seq),
					Jitter:         uint32(rng.Intn(500)),
				}}))
		}
	}
	// Duplicate a few records, keeping them adjacent so the window can recover.
	for k := 0; k < spec.Duplicates && len(rtpRecords) > 0; k++ {
		idx := rng.Intn(len(rtpRecords))
		rec := rtpRecords[idx]
		rtpRecords = append(rtpRecords[:idx+1], append([]wire{rec}, rtpRecords[idx+1:]...)...)
	}

	// Events are written interleaved with media by absolute offset order:
	// media records first, then events at fixed positions.
	for _, rec := range rtpRecords {
		if _, err := w.WriteRecord(ingest.KindRTP, rec.data); err != nil {
			return nil, nil, err
		}
		st.RTPSent++
	}
	for i, rep := range rtcpRecords {
		payload := rep
		truncated := spec.TruncateRTCP && i == len(rtcpRecords)-1
		if truncated {
			n := spec.TruncateBytes
			if n <= 0 {
				n = 4
			}
			if n < len(payload) {
				payload = payload[:len(payload)-n]
			}
			st.TruncatedRTCPOffset = w.Offset()
		}
		if _, err := w.WriteRecord(ingest.KindRTCP, payload); err != nil {
			return nil, nil, err
		}
	}

	events := eventLines(spec)
	for _, line := range events {
		if _, err := w.WriteRecord(ingest.KindEvent, []byte(line)); err != nil {
			return nil, nil, err
		}
	}

	st.Bytes = buf.Bytes()
	return st.Bytes, st, nil
}

// eventLines builds a small client event log. Half the events are relative to
// media time zero, the other half absolute wall clock values.
func eventLines(spec Spec) []string {
	lines := []string{
		fmt.Sprintf("%d join id=1", StartUnixMillis),
		"+100ms stall id=2 text=buffering",
		"+1600ms resume id=2",
		fmt.Sprintf("%d seek id=3 position=1200", StartUnixMillis+3300),
	}
	if spec.GapTicks > 0 {
		// An event inside the injected stall.
		lines = append(lines, "+1400ms freeze id=4 text=stalled")
	}
	for i := 0; i < spec.BadEvents; i++ {
		lines = append(lines, "bogus-time stall id=90 text=no-timestamp")
	}
	return lines
}

func payloadFor(seq uint16) []byte {
	out := make([]byte, PayloadSize)
	for i := range out {
		out[i] = byte(seq) + byte(i)
	}
	return out
}

func min(a, b int) int {
	if a < b {
		return a
	}
	return b
}

func writeFileAtomic(path string, data []byte) error {
	dir := filepath.Dir(path)
	if err := os.MkdirAll(dir, 0o755); err != nil {
		return fmt.Errorf("sample: create %s: %w", dir, err)
	}
	tmp, err := os.CreateTemp(dir, ".sample-*.tmp")
	if err != nil {
		return fmt.Errorf("sample: temp file: %w", err)
	}
	name := tmp.Name()
	defer os.Remove(name)
	if _, err := tmp.Write(data); err != nil {
		tmp.Close()
		return fmt.Errorf("sample: write: %w", err)
	}
	if err := tmp.Sync(); err != nil {
		tmp.Close()
		return fmt.Errorf("sample: sync: %w", err)
	}
	if err := tmp.Close(); err != nil {
		return fmt.Errorf("sample: close: %w", err)
	}
	return os.Rename(name, path)
}
